50	async function createBill(lease: FixtureLease, token = fx.tokens.tenantA): Promise<Bill> {
51	  const r = await api(token).post<Bill>(`/api/leases/${lease.id}/gateway-bills`);
52	  expect(r.status, JSON.stringify(r.body)).toBe(201);
53	  return r.body;
54	}
