56	async function billRow(id: string) {
57	  const rows = await sql<{ status: string; amount_sen: number; paid_at: Date | null; transaction_id: string | null }>(
58	    "select status, amount_sen, paid_at, transaction_id from public.gateway_bills where id = $1",
59	    [id],
60	  );
61	  return rows[0];
62	}
