64	async function billPayments(billId: string) {
65	  return sql<{
66	    id: string;
67	    method: string;
68	    status: string;
69	    amount_sen: number;
70	    unapplied_sen: number;
71	    received_at: Date;
72	    lease_id: string;
73	  }>(
74	    `select id, method, status, amount_sen, unapplied_sen, received_at, lease_id
75	       from public.payments where gateway_bill_id = $1`,
76	    [billId],
77	  );
78	}
