115	describe("R34 R33 forged or missing signatures -> 401, no effect", () => {
116	  it("missing, empty, wrong, wrong-length, non-hex and other-key signatures are 401", async () => {
117	    const { lease, bill } = await freshBill();
118	    const good = signedCallback(bill.billId, bill.amountSen, true, { transaction_id: tx() });
119	    const unsigned: Record<string, string> = { ...good };
120	    delete unsigned.x_signature;
121	    const flipped = good.x_signature.replace(/^./, (c) => (c === "0" ? "1" : "0"));
122	    const cases: Record<string, string>[] = [
123	      unsigned,
124	      { ...good, x_signature: "" },
125	      { ...good, x_signature: flipped },
126	      { ...good, x_signature: good.x_signature.slice(0, 32) },
127	      { ...good, x_signature: `${good.x_signature}00` },
128	      { ...good, x_signature: "z".repeat(64) },
129	      signedCallback(bill.billId, bill.amountSen, true, { transaction_id: tx() }, "not_the_key"),
130	    ];
131	    const rs = await Promise.all(cases.map(hook));
132	    for (const r of rs) {
133	      expect(r.status).toBe(401);
134	      expectErrorBody(r);
135	    }
136	    expect((await billRow(bill.billId)).status).toBe("pending");
137	    expect(await billPayments(bill.billId)).toHaveLength(0);
