409	describe("R35 D7 D10 forced overlap: apply_gateway_callback holds the bill lock until commit", () => {
410	  const applySql = "select * from private.apply_gateway_callback($1::uuid, true, $2::bigint, $3::timestamptz, $4, 'completed')";
411	
412	  it("SQL x SQL: session 2 waits on a Lock while session 1 is uncommitted, then returns 'duplicate'", async () => {
413	    const { bill } = await freshBill();
414	    const c1 = await newConnection();
415	    const c2 = await newConnection();
416	    let second: Promise<pg.QueryResult<{ outcome: string; payment_id: string }>> | undefined;
417	    try {
418	      await c1.query("begin");
419	      const first = await c1.query<{ outcome: string; payment_id: string }>(applySql, [
420	        bill.billId,
421	        bill.amountSen,
422	        "2026-04-01T00:30:12+08:00",
423	        tx(),
424	      ]);
425	      expect(first.rows[0].outcome).toBe("paid");
426	      const pid2 = await backendPid(c2);
427	      second = c2.query(applySql, [bill.billId, bill.amountSen, "2026-04-01T00:30:12+08:00", tx()]);
428	      second.catch(() => undefined);
429	      expect(await waitForPidOnLock(pid2)).toBe("Lock");
430	      await c1.query("commit");
431	      const res = await second;
432	      expect(res.rows[0]).toEqual({ outcome: "duplicate", payment_id: first.rows[0].payment_id });
433	      expect(await billPayments(bill.billId)).toHaveLength(1);
434	    } finally {
435	      await c1.query("rollback").catch(() => undefined);
436	      if (second) await second.catch(() => undefined);
437	      await c1.end();
438	      await c2.end();
439	    }
